/* Bilingual teaching layer: mission context, component inspection and flight UI. */
'use strict';
English.cruise=['Interplanetary transfer','Heliocentric trajectory in the inner Solar System. Medium launcher required; power is specified at operating distance.'];
icons.cruise='↗';
let overlay=null,alarmContext=null,alarmOn=false,lastFlightPhase='',missionClock=null;
const NASA_SOURCES=[
 ['Galileo — NASA Science','https://science.nasa.gov/mission/galileo/'],
 ['Galileo arrival press kit — JPL','https://www.jpl.nasa.gov/news/press_kits/gllarpk.pdf'],
 ['Galileo telecommunications recovery — NASA','https://www.nasa.gov/image-article/july-1995-galileo-reached-jupiter/'],
 ['NASA Systems Engineering Handbook','https://www.nasa.gov/reference/systems-engineering-handbook/'],
 ['JPL Concept Maturity Levels — NASA ASTRA','https://science.nasa.gov/astrophysics/programs/physics-of-the-cosmos/community/astra-initiative-seminar-22-may-2026/'],
 ['NASA Deep Space Network','https://www.nasa.gov/communicating-with-missions/dsn/'],
 ['Galileo telecom system design — JPL','https://descanso.jpl.nasa.gov/DPSummary/Descanso5--Galileo.pdf']
];
const oldMissions=missions;
missions=()=>{const a=oldMissions();a[0]={name:t('O ÚLTIMO SINAL','THE LAST SIGNAL'),brief:t('Recife · 2049. A Marco 04 cruza o espaço interplanetário após observar Marte e armazenar dados de uma anomalia atmosférica. Na metade da simulação, sua antena principal trava. A estação Recife recebe o último sinal e coordena a recuperação.','Recife · 2049. Marco 04 cruises through interplanetary space after observing Mars and storing data on an atmospheric anomaly. Halfway through the simulated outbound leg, its main antenna jams. Recife receives the last signal and coordinates recovery.'),goal:t('Recuperar evidências atmosféricas, solares e térmicas pela antena reserva.','Recover atmospheric, solar and thermal evidence through the backup antenna.'),challenge:t('Espaço profundo exige trajetória interplanetária. Os painéis representam energia disponível na distância de operação no Sistema Solar interior; não uma missão a Júpiter.','Deep space requires an interplanetary trajectory. Panel ratings represent available power at operating distance in the inner Solar System, not a Jupiter mission.'),hyp:[t('Variação solar','Solar variation'),t('Composição atmosférica','Atmospheric composition'),t('Aquecimento da superfície','Surface warming')]};return a};
function segments(){return [[t('Segmento de Lançamento','Launch Segment'),t('O foguete coloca a massa na trajetória correta. Em voo, não é possível trocar o lançador.','The rocket places mass on the correct trajectory. The launcher cannot be changed in flight.')],[t('Segmento Espacial','Space Segment'),t('Sonda, instrumentos, energia, computador e antenas trabalham juntos para coletar e enviar ciência.','The probe, instruments, power, computer and antennas work together to collect and send science.')],[t('Segmento Terrestre · Recife','Ground Segment · Recife'),t('A estação fictícia de Recife recebe o sinal. Antenas parceiras da DSN aumentam a capacidade de escuta no cenário.','The fictional Recife station receives the signal. Partner DSN antennas improve listening capability in this scenario.')],[t('Segmento de Usuários','User Segment'),t('Cientistas precisam de dados úteis, não apenas de uma nave funcionando. Eles avaliam cobertura, qualidade e evidências.','Scientists need useful data, not just a functioning spacecraft. They assess coverage, quality and evidence.')]]}
function realHistory(){return `<p>${t('Em abril de 1991, a antena de alto ganho da Galileo não abriu completamente. Seu projeto previa até 134.400 bits/s. Sem as melhorias, a alternativa de baixo ganho teria cerca de 10 bits/s nas condições de Júpiter — não uma taxa fixa de toda a viagem.','In April 1991, Galileo’s high-gain antenna failed to deploy fully. It was designed for up to 134,400 bits/s. Without improvements, the low-gain alternative would have delivered about 10 bits/s under Jupiter conditions, not a fixed rate throughout the journey.')}</p><p>${t('A recuperação combinou software de voo e de solo, compressão, melhores códigos e combinação de antenas. A NASA descreve uma taxa efetiva de 1–2 kbit/s após as melhorias. Esse trabalho levou anos; a crise de 60 segundos e a redução de 90% são regras fictícias deste jogo.','Recovery combined flight and ground software, compression, improved codes and antenna arraying. NASA describes an effective rate of 1–2 kbit/s after upgrades. This work took years; the 60-second crisis and 90% reduction are fictional game rules.')}</p><p class="hint">${t('Priorizar energia aqui é uma analogia de gestão de recursos. Desligar cargas não destravou a antena real. A estação Recife + DSN é uma parceria fictícia, sem vínculo operacional real com a NASA.','Power prioritization here is a resource-management analogy. Turning off loads did not unjam the real antenna. Recife + DSN is a fictional partnership with no real NASA operational connection.')}</p>`}
const lessons={
 optical:[['Observa cores para comparar terreno, nuvens, água e vegetação.','Observes colors to compare terrain, clouds, water and vegetation.'],['Sem visibilidade ou sob nuvens, o mapa fica incompleto; não substitui um sensor térmico.','Without visibility or under clouds, mapping is incomplete; it cannot replace a thermal sensor.']],
 radar:[['Envia ondas de rádio e lê o eco. Observa água mesmo com nuvens e à noite.','Sends radio waves and reads their echo. Observes water through clouds and at night.'],['Sem radar, nuvens podem esconder as áreas inundadas. Energia insuficiente impede emitir os pulsos.','Without radar, clouds can hide flooded areas. Insufficient power prevents pulse transmission.']],
 thermal:[['Mede o calor emitido pela superfície; não mede diretamente a temperatura do ar.','Measures heat emitted by the surface, not air temperature directly.'],['Sem ele, faltam medidas diretas da temperatura superficial para comparar regiões.','Without it, direct surface temperature measurements are missing.']],
 solar:[['Mede a energia recebida do Sol para testar uma hipótese solar.','Measures incoming solar energy to test a solar hypothesis.'],['Sem essa medida, atribuir uma anomalia ao Sol fica sem teste próprio.','Without this measurement, blaming the Sun lacks an independent test.']],
 atmos:[['Separa a luz em faixas para investigar assinaturas da atmosfera.','Splits light into bands to investigate atmospheric signatures.'],['Sem esse instrumento, a hipótese atmosférica fica com uma lacuna de evidência.','Without it, the atmospheric hypothesis has an evidence gap.']],
 basic:[['Converte luz solar em eletricidade para a plataforma e os instrumentos.','Converts sunlight into electricity for the platform and instruments.'],['Se a demanda superar a geração, sensores e rádio não operam juntos. Longe do Sol a energia solar diminui.','If demand exceeds generation, sensors and radio cannot operate together. Solar power decreases farther from the Sun.']],
 large:[['Uma área maior de painéis fornece mais energia disponível na distância de operação.','A larger panel area provides more available power at operating distance.'],['Painéis maiores pesam e custam mais; sem folga elétrica a resposta à crise pode falhar.','Larger panels weigh and cost more; without electrical margin, crisis response can fail.']],
 low:[['Conjunto simplificado de rádio e antena em banda S, para enviar os arquivos à Terra.','Simplified S-band radio and antenna package for sending files to Earth.'],['Capacidade baixa acumula arquivos a bordo e deixa ciência sem transmissão antes do fim da janela.','Low capacity builds an onboard backlog and leaves science unsent before the window closes.']],
 high:[['Conjunto simplificado de rádio e antena de maior capacidade em banda X.','Simplified higher-capacity X-band radio and antenna package.'],['Uma antena potente ainda pode travar. Banda de frequência, sozinha, não determina a taxa de dados.','A capable antenna can still jam. Frequency band alone does not determine data rate.']],
 leo:[['Mantém um satélite perto da Terra para observar detalhes regionais.','Keeps a satellite near Earth for detailed regional observations.'],['Uma órbita terrestre baixa não leva uma sonda a Marte; revisitas lentas deixam lacunas.','Low Earth orbit does not take a probe to Mars; slow revisit leaves gaps.']],
 sun:[['Permite comparar imagens terrestres com condições de iluminação parecidas.','Allows Earth images to be compared under similar lighting.'],['Exige um lançador compatível. Não é uma trajetória de espaço profundo.','Requires a compatible launcher. It is not a deep-space trajectory.']],
 cruise:[['Leva a sonda para fora da órbita terrestre em uma transferência heliocêntrica rumo a Marte.','Takes the probe beyond Earth orbit on a heliocentric transfer toward Mars.'],['Sem energia de lançamento suficiente, a sonda não alcança a trajetória. Tempos e atraso de luz são comprimidos no jogo.','Without enough launch energy, the probe cannot reach its trajectory. Travel time and light delay are compressed in the game.']],
 light:[['Entrega uma carga menor à órbita terrestre baixa.','Delivers a smaller payload to low Earth orbit.'],['Massa excessiva ou uma trajetória mais exigente impedem a entrega. Não basta comparar só a massa da nave.','Excess mass or a more demanding trajectory prevents delivery. Spacecraft mass alone is not enough.']],
 medium:[['Entrega cargas maiores ou trajetórias mais exigentes, dentro dos limites simplificados.','Delivers larger payloads or more demanding trajectories within simplified limits.'],['O limite depende do destino: 620 kg em órbita terrestre; 450 kg na transferência. Escolher mais instrumentos pode ultrapassá-lo.','Capacity depends on destination: 620 kg in Earth orbit; 450 kg on transfer. More instruments can exceed it.']]
};
function componentLesson(id){const o=Object.values(E.catalog).flat().find(x=>x.id===id),l=lessons[id];let costs=`${o.cost} ${t('créditos','credits')} · ${o.mass||0} kg`;if(o.power)costs+=` · ${o.power} W · ${o.data} GB/${t('dia','day')}`;if(o.supply)costs+=` · ${t('fornece','provides')} ${o.supply} W`;if(['low','high'].includes(id))costs+=` · ${o.capacity} GB/${t('dia','day')}`;if(['light','medium'].includes(id))costs+=` · ${t('até','up to')} ${o.capacity} kg`;return `<h2>${itemName(id)}</h2><div class="lesson-topic"><h3>${t('Para que serve','What it does')}</h3><p>${t(...l[0])}</p></div><div class="lesson-topic"><h3>${t('Custo e trade-off','Cost and trade-off')}</h3><p>${costs}.</p><p>${t('Mais capacidade pode exigir mais massa e orçamento. Recursos gastos aqui deixam menos reserva para o solo.','More capability can require more mass and budget. Resources spent here leave less reserve for ground support.')}</p></div><div class="lesson-topic"><h3>${t('Risco se faltar','Risk if missing')}</h3><p>${t(...l[1])}</p></div><p class="hint">${t('Valores didáticos fictícios. GB/dia é uma escala de planejamento do jogo, não uma taxa real da Galileo.','Fictional teaching values. GB/day is a game planning scale, not Galileo’s real data rate.')}</p>`}
function openTeaching(kind,id){overlay={kind,id};drawTeaching()}
function drawTeaching(){let html='';if(overlay.kind==='inspect')html=componentLesson(overlay.id);if(overlay.kind==='sources')html=`<h2>${t('Fontes NASA / Referências','NASA Sources / References')}</h2><ul>${NASA_SOURCES.map(([title,url])=>`<li><a href="${url}" target="_blank" rel="noopener">${title}</a></li>`).join('')}</ul>${realHistory()}<p class="hint">${t('Projeto educativo independente; não é um produto da NASA. CML organiza a maturação do conceito, não certifica a nave do jogo.','Independent educational project; not a NASA product. CML structures concept maturation, not certification of the game spacecraft.')}</p>`;if(overlay.kind==='briefing')html=`<div class="eyebrow">RECIFE · 2049 / LAST SIGNAL</div><h2>${t('O último sinal não é o fim.','The last signal is not the end.')}</h2><p>${t('Projete a missão antes de lançar. Em voo, a antena falha: já não é possível trocar a nave. Use software, energia e apoio terrestre para recuperar os dados.','Design the mission before launch. In flight, the antenna fails: replacing the spacecraft is no longer possible. Use software, power and ground support to recover the data.')}</p><div class="two">${segments().map(([h,p])=>`<section class="lesson-topic"><h3>${h}</h3><p>${p}</p></section>`).join('')}</div><details><summary>${t('Inspiração: Galileo, 1991','Inspiration: Galileo, 1991')}</summary>${realHistory()}</details><p class="hint">${t('Organização didática da arquitetura em quatro segmentos; o handbook orienta pensar no sistema completo.','A four-segment teaching architecture; the handbook encourages whole-system thinking.')}</p><button id="briefingGo" class="primary">${t('Entendi · formar equipe →','Understood · form crew →')}</button>`;
 $('#modalBody').innerHTML=`<label class="small" for="teachingLang">${t('Idioma','Language')} <select id="teachingLang"><option value="pt">PT-BR</option><option value="en">EN</option></select></label>`+html;if(!$('#modal').open)$('#modal').showModal();$('#teachingLang').value=lang;$('#teachingLang').onchange=()=>{lang=$('#teachingLang').value;localStorage.setItem('m04-language',lang);render();drawTeaching()};if($('#briefingGo'))$('#briefingGo').onclick=()=>{overlay=null;$('#modal').close();screen=2;players=[];revealIndex=0;showRole=false;state=E.initial();review=false;event=false;render()};
}
$('#modal').addEventListener('close',()=>overlay=null);
const originalHeader=header;header=()=>{originalHeader();$('#sources').textContent=t('Fontes NASA / Referências','NASA Sources / References')};
$('#sources').onclick=()=>openTeaching('sources');
$('#language').onchange=()=>{lang=$('#language').value;localStorage.setItem('m04-language',lang);render();if(overlay)drawTeaching()};
const originalHome=home;home=()=>{originalHome();$('#start').onclick=()=>openTeaching('briefing');const p=$('#view .hero p');if(p)p.textContent=t('Uma sonda em espaço profundo. Uma antena travada. Quatro pessoas para recuperar a ciência a partir de Recife.','A probe in deep space. A jammed antenna. Four people recovering science from Recife.');$('#view').insertAdjacentHTML('beforeend',`<div class="notice">${t('Inspirado pela Galileo: planejem sensores e reservas; na simulação, enfrentem uma janela de crise de 60 segundos.','Inspired by Galileo: plan sensors and reserves, then face a 60-second crisis window in the simulation.')}</div>`)};
const originalBrief=brief;brief=()=>{originalBrief();$('#view').insertAdjacentHTML('beforeend',`<div class="panel review"><h3>${t('Uma missão, quatro segmentos','One mission, four segments')}</h3><div class="two">${segments().map(([h,p])=>`<section><h3>${h}</h3><p class="small">${p}</p></section>`).join('')}</div><p class="notice">${t('Guardem 20 créditos para antenas terrestres e potência para 20 W extras no rádio, mais 6 W se ativarem compressão. Todos os controles têm consequências.','Keep 20 credits for ground antennas and power for 20 extra radio watts, plus 6 W if compression is enabled. Every control has consequences.')}</p></div>`)};
validation=()=>{const x=E.totals(state),a=[];if(!state.instruments.length)a.push(t('Sem instrumento, a nave não gera evidência científica. Selecione pelo menos um.','Without an instrument, the craft generates no scientific evidence. Select at least one.'));if(x.cost>160)a.push(t('Orçamento excedido: o dinheiro gasto em componentes não está disponível para desenvolvimento nem para a rede de antenas. Reduza custos.','Budget exceeded: component spending is unavailable for development or antenna support. Reduce costs.'));if(x.mass>x.load)a.push(t('Massa excede a capacidade deste lançador para a trajetória selecionada. Escolha um foguete mais potente ou reduza instrumentos.','Mass exceeds this launcher’s capacity for the selected trajectory. Choose a stronger rocket or reduce instruments.'));if(x.power>x.supply)a.push(t('Os instrumentos consomem mais Watts que a geração disponível. Eles não podem operar juntos: amplie os painéis ou reduza a carga.','Instruments consume more watts than the available supply. They cannot operate together: expand panels or reduce payload.'));if(state.orbit==='sun'&&state.launcher==='light')a.push(t('O lançador leve não entrega a energia orbital exigida pela órbita heliossíncrona. Use o lançador médio.','The light launcher cannot provide the orbital energy needed for sun-synchronous orbit. Use the medium launcher.'));if(state.mission===0&&state.orbit!=='cruise')a.push(t('Órbita terrestre não leva a sonda ao espaço interplanetário. Selecione transferência interplanetária.','Earth orbit does not take the probe into interplanetary space. Select interplanetary transfer.'));if(state.mission!==0&&state.orbit==='cruise')a.push(t('Esta missão observa a Terra. Uma transferência para Marte perde a cobertura necessária; selecione uma órbita terrestre.','This mission observes Earth. A Mars transfer loses the required coverage; select an Earth orbit.'));if(state.orbit==='cruise'&&state.launcher!=='medium')a.push(t('A transferência interplanetária exige o lançador médio, limitado a 450 kg nesse destino.','Interplanetary transfer requires the medium launcher, limited to 450 kg for this destination.'));return a};
const originalChange=change;change=(key,value)=>{if(room){originalChange(key,value);return}if(key==='mission'){state.mission=value;state.orbit=value===0?'cruise':'leo';if(value===0)state.launcher='medium';state.flight=null;render()}else originalChange(key,value)};
const originalResources=resources;resources=()=>originalResources().replace(t('Dados/ciclo','Data/cycle'),t('Dados gerados / link','Data generated / link')).replace(/ UD| DU/g,' GB/'+t('dia','day')).replace('</aside>',`<div class="notice small">${t('Reserva disponível','Available reserve')}: ${E.totals(state).reserve} CR<br>${t('Reforço terrestre: 20 CR. Rádio de emergência: +20 W. Compressão: +6 W.','Ground support: 20 CR. Emergency radio: +20 W. Compression: +6 W.')}</div></aside>`);
const originalBuild=build;build=()=>{originalBuild();if(event)return;document.querySelectorAll('[data-item]').forEach(b=>{const id=b.dataset.item;const wrapper=document.createElement('article');wrapper.className='component-wrapper';b.parentNode.insertBefore(wrapper,b);wrapper.appendChild(b);const info=document.createElement('button');info.className='inspect';info.dataset.inspect=id;info.textContent=t('? Inspecionar','? Inspect');info.setAttribute('aria-label',t('Inspecionar ','Inspect ')+itemName(id));info.onclick=()=>openTeaching('inspect',id);wrapper.appendChild(info)});const x=E.totals(state),h=[];if(x.data>x.capacity)h.push(t(`Gargalo de dados: os instrumentos geram ${x.data} GB/dia, mas a antena transmite ${x.capacity} GB/dia. O excedente fica a bordo e parte da ciência pode ser perdida.`,`Data bottleneck: instruments generate ${x.data} GB/day but the antenna sends ${x.capacity} GB/day. Excess data stays onboard and science may be lost.`));if(x.reserve<20)h.push(t(`Só restam ${x.reserve} créditos: o reforço terrestre custa 20. Reservem orçamento antes do lançamento.`,`Only ${x.reserve} credits remain: ground support costs 20. Reserve budget before launch.`));if(x.supply-x.power<26)h.push(t('A folga elétrica é menor que 26 W: rádio de emergência e compressão podem exigir desligar sensores secundários.','Electrical margin is below 26 W: emergency radio and compression may require shutting down secondary sensors.'));if(!h.length)h.push(t('Há margem de comunicação, potência e orçamento, mas a falha da antena ainda exigirá decisões em voo.','There is communications, power and budget margin, but antenna failure will still require in-flight decisions.'));$('#confirmBuild').closest('.actions').insertAdjacentHTML('beforebegin',`<div class="notice" aria-live="polite">${h.join('<br><br>')}</div>`);if(!room&&review)$('#confirmBuild').onclick=()=>{E.startFlight(state);event=true;lastFlightPhase='';primeAudio();render()};else if(room&&review){const launch=$('#confirmBuild').onclick;$('#confirmBuild').onclick=()=>{primeAudio();launch()}}};
function primeAudio(){try{alarmContext??=new(window.AudioContext||window.webkitAudioContext)();alarmContext.resume()}catch{}}
function alarm(){if(!alarmOn||!alarmContext)return;try{const o=alarmContext.createOscillator(),g=alarmContext.createGain();o.type='square';o.frequency.value=660;g.gain.setValueAtTime(.045,alarmContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,alarmContext.currentTime+.4);o.connect(g);g.connect(alarmContext.destination);o.start();o.stop(alarmContext.currentTime+.4)}catch{}}
function command(action){if(room)act('emergency',{action});else{try{E.commandFlight(state,action);save();render()}catch(e){showModal(`<p class="notice error">${err(e.message)}</p>`)}}}
errorText.RESERVE=()=>t('Sem reserva: o reforço terrestre exige 20 créditos não gastos.','No reserve: ground support requires 20 unspent credits.');errorText.POWER=()=>t('Sem potência para o computador de compressão. Desligue sensores secundários primeiro.','No power for compression computing. Shut down secondary sensors first.');errorText.NO_SECONDARY=()=>t('Não há sensor secundário para desligar. A prioridade preserva o instrumento principal.','There is no secondary sensor to shut down. Priority preserves the primary instrument.');
function emergencyCard(action,title,description,enabled,reason){const active=state.flight.actions[action];return `<article class="panel"><h3>${title}</h3><p class="small">${description}</p><button data-emergency="${action}" class="${active?'secondary':'primary'}" ${active||!enabled||!canControl()?'disabled':''}>${active?t('✓ Aplicado','✓ Applied'):t('Aplicar comando','Apply command')}</button>${!enabled&&!active?`<p class="hint">${reason}</p>`:''}</article>`}
eventScreen=()=>{if(!state.flight){view(`<div class="notice">${t('Esta partida usa uma simulação antiga. Volte à montagem e lance novamente.','This game uses an older simulation. Return to assembly and launch again.')}</div><button id="resetLegacy">${t('Voltar à montagem','Return to assembly')}</button>`);$('#resetLegacy').onclick=()=>{event=false;review=false;state.flight=null;render()};return}const f=state.flight,m=E.flightModel(state),crisis=f.phase!=='cruise',canPower=state.instruments.some(id=>id!==E.primary(state)),canCompress=m.consumption+6<=m.supply;
 view(`<div class="eyebrow">04 / ${t('Simulação de missão','Mission simulation')}</div><h2 class="${crisis?'crisis-title':''}">${crisis?t('ALERTA CRÍTICO: LAST SIGNAL','CRITICAL ALERT: LAST SIGNAL'):t('Marco 04 · viagem em andamento','Marco 04 · mission underway')}</h2><div class="flight-path" aria-hidden="true"><span>RECIFE</span><span class="probe">▦ →</span><span>${state.mission===0?t('ESPAÇO PROFUNDO','DEEP SPACE'):t('ÓRBITA TERRESTRE','EARTH ORBIT')}</span></div><div id="telemetry" class="panel" aria-live="off"></div><div class="actions"><button id="alarmToggle">${alarmOn?t('Som do alerta: ligado','Alert sound: on'):t('Som do alerta: desligado','Alert sound: off')}</button></div><p class="hint">${t('Alerta visual sempre ativo. Som opcional; habilite pelo botão. Tempo e propagação de rádio são comprimidos nesta simulação.','Visual alert is always enabled. Sound is optional; enable it with the button. Time and radio propagation are compressed in this simulation.')}</p>${crisis?`<div class="notice error" role="alert">${t('Antena principal obstruída · banda reduzida em 90%. A telemetria normal está pausada. Operem os controles antes de fechar a janela.','Main antenna obstructed · bandwidth reduced by 90%. Normal telemetry is paused. Operate controls before the window closes.')}</div><div class="grid emergency-grid">${emergencyCard('power',t('1 / Prioridade de energia','1 / Power priority'),t('Desligue sensores secundários e priorize o transmissor. Libera Watts, aumenta o link em 1,8× e reduz novas amostras científicas em 10%. A antena continua travada.','Shut down secondary sensors and prioritize the transmitter. Frees watts, boosts the link 1.8× and reduces new science sampling by 10%. The antenna remains jammed.'),canPower,err('NO_SECONDARY'))}${emergencyCard('compression',t('2 / Compressão a bordo','2 / Onboard compression'),t('Comprima os pacotes 3:1. Exige 6 W de computação e retém 90% da qualidade científica. Não aumenta a taxa física do rádio.','Compress packets 3:1. Requires 6 W of computing and retains 90% science quality. Does not increase the physical radio rate.'),canCompress,err('POWER'))}${emergencyCard('ground',t('3 / Reforço terrestre','3 / Ground support'),t('Recife + antenas parceiras DSN: gaste 20 créditos de reserva para triplicar a recepção efetiva do sinal fraco. Não cria energia na sonda.','Recife + partner DSN antennas: spend 20 reserve credits to triple effective weak-signal reception. Does not create spacecraft power.'),m.reserve>=20,err('RESERVE'))}</div><div class="actions"><button id="closeWindow" ${disabled()}>${t('Encerrar janela e gerar dossiê','Close window and generate dossier')}</button></div><p class="hint">${t('Encerrar agora preserva apenas o que já chegou. Não é preciso aplicar todos os comandos; compare custo, energia e recuperação.','Closing now keeps only data already received. You do not need every command; compare cost, power and recovery.')}</p>`:`<p class="notice">${t('Acompanhando a primeira metade da viagem. O alerta ocorrerá aos 8 segundos. Preparem o plano de emergência.','Tracking the first half of the journey. The alert occurs at 8 seconds. Prepare your emergency plan.')}</p>`}${controlNote()}${onlineChat()}`);
 $('#alarmToggle').onclick=()=>{alarmOn=!alarmOn;primeAudio();if(alarmOn)alarm();render()};document.querySelectorAll('[data-emergency]').forEach(b=>b.onclick=()=>command(b.dataset.emergency));if($('#closeWindow'))$('#closeWindow').onclick=()=>{if(room)act('finish',{choice:'close'});else{E.closeFlight(state);screen=5;render()}};bindChat();updateTelemetry();
};
function updateTelemetry(){const box=$('#telemetry');if(!box||!state.flight)return;const f=state.flight,m=E.flightModel(state),cruising=f.phase==='cruise',now=Date.now(),remaining=Math.max(0,Math.ceil((f.deadline-now)/1000)),r=E.evaluate(state);box.innerHTML=`<div class="telemetry-grid"><div><b>${t('Janela restante','Window remaining')}</b><strong class="clock">${f.phase==='cruise'?'—':remaining+' s'}</strong></div><div><b>${t('Arquivos recuperados','Recovered files')}</b><strong>${r.delivered}%</strong><span>${f.recovered.toFixed(2)} / ${m.demand} GB</span></div><div><b>${t('Link modelado','Modeled link')}</b><strong>${(cruising?m.nominal:m.link).toFixed(2)} GB/${t('dia','day')}</strong><span>${cruising?t('Sinal nominal · aguardando coleta de telemetria','Nominal signal · awaiting telemetry'):t('Nominal','Nominal')+': '+m.nominal+' → '+m.damaged.toFixed(2)}</span></div><div><b>${t('Após compressão','After compression')}</b><strong>${(cruising?m.nominal:m.effective).toFixed(2)} GB/${t('dia','day')}</strong><span>${t('equivalentes originais','original equivalents')}</span></div><div><b>${t('Potência exigida','Required power')}</b><strong>${cruising?E.totals(state).power:m.consumption}/${m.supply} W</strong><span>${t('Watts liberados','Watts freed')}: ${m.freed}</span></div><div><b>${t('Reserva','Reserve')}</b><strong>${m.reserve} CR</strong><span>${t('Gasto total','Total spent')}: ${m.cost}/160</span></div></div>${!cruising&&m.powerRatio<1?`<p class="notice error">${t('Sem potência suficiente para o transmissor: o link cai proporcionalmente. Desligue cargas secundárias para liberar energia.','Not enough transmitter power: link performance falls proportionally. Shed secondary loads to free power.')}</p>`:''}<div class="track"><div class="fill" style="width:${r.delivered}%"></div></div><p class="hint">${t('Escala fictícia: os 60 segundos da janela representam um período normalizado de transmissão. A recuperação integra a taxa disponível ao longo do tempo; ativar algo no último segundo não recupera dados retroativamente.','Fictional scale: the 60-second window represents a normalized transmission period. Recovery integrates available rate over time; a last-second action cannot recover earlier data retroactively.')}</p>`}
function comparisonTable(){const a=state.flight.actions;return `<h3>${t('História Real da NASA','Real NASA History')}</h3>${realHistory()}<div class="table-scroll"><table class="comparison"><thead><tr><th>${t('Sua decisão','Your decision')}</th><th>${t('Galileo real','Real Galileo')}</th></tr></thead><tbody><tr><td>${t('Prioridade de energia','Power priority')}: ${a.power?t('ativada','enabled'):t('não ativada','not enabled')}</td><td>${t('A reorganização de cargas é analogia do jogo; não abriu a antena real.','Load rearrangement is a game analogy; it did not open the real antenna.')}</td></tr><tr><td>${t('Compressão','Compression')}: ${a.compression?t('ativada','enabled'):t('não ativada','not enabled')}</td><td>${t('Software, compressão e codificação reduziram o volume transmitido e melhoraram o retorno.','Software, compression and coding reduced transmitted volume and improved return.')}</td></tr><tr><td>${t('Antenas terrestres','Ground antennas')}: ${a.ground?t('acionadas','enabled'):t('não acionadas','not enabled')}</td><td>${t('A combinação de antenas e melhorias nos receptores ajudaram a receber o sinal fraco.','Antenna arraying and receiver improvements helped receive the weak signal.')}</td></tr></tbody></table></div>`}
results=()=>{if(!state.flight){view(`<p>${t('Reinicie a missão para gerar o novo dossiê.','Restart the mission to generate the new dossier.')}</p><button id="oldRetry">${t('Tentar novamente','Try again')}</button>`);$('#oldRetry').onclick=()=>{event=false;screen=4;render()};return}const r=E.evaluate(state),m=E.flightModel(state),x=E.totals(state),f=state.flight;const outcome=r.science>=65?t('MISSÃO BEM-SUCEDIDA','MISSION SUCCESS'):r.science>=35?t('SUCESSO PARCIAL','PARTIAL SUCCESS'):t('MISSÃO SEM SUCESSO','MISSION UNSUCCESSFUL');const points=[t(`Valor científico dos sensores: ${r.value}/100. A seleção de instrumentos define quais hipóteses podem ser testadas.`,`Sensor science value: ${r.value}/100. Instrument selection defines which hypotheses can be tested.`),t(`Energia: ${m.consumption}/${m.supply} W exigidos na crise; ${m.freed} W liberados. Potência insuficiente reduz o link.`,`Power: ${m.consumption}/${m.supply} W required during crisis; ${m.freed} W freed. Insufficient power reduces the link.`),t(`Massa: ${x.mass}/${x.load} kg na trajetória escolhida. Mais carga reduz a margem do lançador.`,`Mass: ${x.mass}/${x.load} kg for the chosen trajectory. More payload reduces launcher margin.`),t(`Orçamento: ${m.cost}/160 créditos; ${m.reserve} restantes. O apoio terrestre custa 20 e só existe se houver reserva.`,`Budget: ${m.cost}/160 credits; ${m.reserve} remaining. Ground support costs 20 and requires reserves.`),t(`Dados: ${f.recovered.toFixed(2)}/${x.data} GB recuperados (${r.delivered}%). Qualidade retida: ${Math.round(r.quality*100)}%; amostragem: ${Math.round(r.sampling*100)}%.`,`Data: ${f.recovered.toFixed(2)}/${x.data} GB recovered (${r.delivered}%). Retained quality: ${Math.round(r.quality*100)}%; sampling: ${Math.round(r.sampling*100)}%.`)];const formula=t(`Ciência = ${r.value} × ${(r.delivered/100).toFixed(2)} recuperado × ${r.quality} qualidade × ${r.sampling} amostragem × ${r.revisit} cobertura = ${r.science}% (arredondado com frações internas não arredondadas).`,`Science = ${r.value} × ${(r.delivered/100).toFixed(2)} recovered × ${r.quality} quality × ${r.sampling} sampling × ${r.revisit} coverage = ${r.science}% (rounded using unrounded internal fractions).`);const mole=players.find(p=>p.impostor);
 view(`<div class="eyebrow">05 / ${t('Dossiê pós-missão','Post-mission dossier')}</div><h2>${outcome}</h2><div class="two"><section class="panel"><div class="score">${r.score}/100</div>${meter(t('Retorno científico','Scientific return'),r.science,100,'%')}${meter(t('Dados recuperados','Recovered data'),r.delivered,100,'%')}<p class="small">${t('Resultado: ≥65% de ciência é sucesso; ≥35% é parcial; abaixo disso, insucesso. Pontuação geral: 70% ciência + 20% viabilidade + 10% eficiência.','Outcome: ≥65% science is success; ≥35% is partial; below that is failure. Overall score: 70% science + 20% feasibility + 10% efficiency.')}</p></section><section class="panel"><h3>${t('Por que esse resultado?','Why this outcome?')}</h3><p>${formula}</p><p>${t('A crise foi encerrada após','The crisis ended after')} ${Math.max(0,Math.round(((f.endedAt||f.deadline)-f.crisisAt)/1000))} s. ${t('Comandos tardios tiveram menos tempo para recuperar dados.','Late commands had less time to recover data.')}</p><p>${t('O impostor era','The impostor was')}: <strong>${escapeHTML(mole?.name||'—')}</strong>. ${t('Encontrá-lo não substitui a recuperação da ciência.','Finding them does not replace science recovery.')}</p></section></div><section class="panel review"><h3>${t('Balanço de engenharia','Engineering balance')}</h3><ul>${points.map(p=>`<li>${p}</li>`).join('')}</ul></section><div class="results"><section class="panel"><h3>${t('O que deu certo?','What went right?')}</h3><p>${t('A nave passou pelas verificações de lançamento.','The craft passed launch checks.')} ${r.delivered>0?t('Parte do sinal foi recuperada pela antena reserva.','Some signal was recovered through the backup antenna.'):t('Nenhum dado chegou antes do fechamento.','No data arrived before closure.')}</p></section><section class="panel"><h3>${t('O que deu errado?','What went wrong?')}</h3><p>${t('A antena perdeu 90% da capacidade.','The antenna lost 90% of capacity.')} ${r.delivered<100?t('Arquivos ficaram a bordo quando a janela fechou.','Files remained onboard when the window closed.'):t('A recuperação foi completa, mas a compressão e a redução de amostras podem limitar o valor científico.','Recovery was complete, but compression and reduced sampling can limit science value.')}</p></section><section class="panel"><h3>${t('O que pode melhorar?','What can improve?')}</h3><p>${t('Reservem energia e 20 créditos. Comparem os sensores com a hipótese. Apliquem comandos cedo e esperem a recuperação antes de encerrar.','Reserve power and 20 credits. Match sensors to the hypothesis. Apply commands early and allow recovery before closing.')}</p></section></div><section class="panel">${comparisonTable()}</section><details class="panel review"><summary>${t('Configuração e registro de comandos','Configuration and command log')}</summary>${selectedList()}<ul>${f.log.map(l=>`<li>${t('Aos','At')} ${l.elapsed} s: ${actionName(l.action)}</li>`).join('')||`<li>${t('Nenhum comando aplicado.','No commands applied.')}</li>`}</ul></details><div class="actions"><button id="retry" class="primary" ${disabled()}>${t('Reprojetar e tentar novamente','Redesign and retry')}</button><button id="returnHome">${t('Voltar ao início','Return home')}</button><button id="download">${t('Baixar dossiê','Download dossier')}</button><button id="dossierSources">${t('Fontes NASA','NASA Sources')}</button></div>${onlineChat()}`);
 $('#retry').onclick=()=>{review=false;event=false;if(room)act('retry');else{state.flight=null;screen=4;render()}};$('#returnHome').onclick=()=>{exitRoom();screen=1;render()};$('#dossierSources').onclick=()=>openTeaching('sources');$('#download').onclick=()=>{const text=['MARCO 04 SPACE · RECIFE · 2049',outcome,...points,formula,...f.log.map(l=>l.elapsed+' s: '+actionName(l.action)),t('História real: Galileo falhou ao abrir a antena em abril de 1991. Software, compressão e antenas terrestres ajudaram a salvar a ciência. Priorizar energia é analogia; a antena não foi reaberta.','Real history: Galileo’s antenna failed to deploy in April 1991. Software, compression and ground antennas helped save science. Power prioritization is an analogy; the antenna was not reopened.'),...NASA_SOURCES.map(([title,url])=>title+': '+url),t('Missão de 2049 e parâmetros são fictícios.','The 2049 mission and parameters are fictional.')].join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='marco04-dossier.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};bindChat();
};
function actionName(key){return {power:t('Prioridade de energia','Power priority'),compression:t('Compressão de dados','Data compression'),ground:t('Reforço terrestre','Ground support')}[key]}
missionClock=setInterval(()=>{if(screen!==4||!event||!state.flight)return;const before=state.flight.phase;if(!room){E.tickFlight(state);save();if(state.flight.closed){screen=5;render();return}}const phase=state.flight.phase;if(phase!==lastFlightPhase){lastFlightPhase=phase;if(phase==='crisis')alarm();render()}else updateTelemetry()},500);
render();
